def can_chain(dominoes):
    """Return a closed chain using every domino, or None if impossible.

    A valid chain has matching ends on neighboring stones and matching
    ends on the first and last stones.
    """
    if not dominoes:
        return []

    # In a closed chain every number appears an even number of times,
    # so any odd count rules out a solution immediately.
    degree = {}
    for left, right in dominoes:
        degree[left] = degree.get(left, 0) + 1
        degree[right] = degree.get(right, 0) + 1
    if any(count % 2 for count in degree.values()):
        return None

    first = tuple(dominoes[0])
    remaining = [tuple(d) for d in dominoes[1:]]

    def search(remaining, chain, tail):
        if not remaining:
            return chain if chain[0][0] == tail else None
        for i, (left, right) in enumerate(remaining):
            if left == tail:
                result = search(
                    remaining[:i] + remaining[i + 1:],
                    chain + [(left, right)],
                    right,
                )
            elif right == tail:
                result = search(
                    remaining[:i] + remaining[i + 1:],
                    chain + [(right, left)],
                    left,
                )
            else:
                continue
            if result is not None:
                return result
        return None

    # A closed chain can be rotated and reversed, so it is enough to
    # start with the first input domino in either orientation.
    for start in ((first[0], first[1]), (first[1], first[0])):
        result = search(remaining, [start], start[1])
        if result is not None:
            return result
    return None

